const assert = require('assert');
const { createStore } = require('../src/store');
const { createApi } = require('../src/api');

function setup(stock = 10) {
  let now = 1000;
  const s = createStore({ clock: () => now });
  s.addItem('A', stock);
  return { s, advance: (ms) => { now += ms; } };
}

test('reserve returns unique string ids and reduces availability only', () => {
  const { s } = setup();
  const a = s.reserve('A', 3, 1000);
  const b = s.reserve('A', 2, 1000);
  assert.strictEqual(typeof a, 'string');
  assert.notStrictEqual(a, b);
  assert.strictEqual(s.getAvailable('A'), 5);
  assert.strictEqual(s.getStock('A'), 10);
});
test('reserve validates qty', () => {
  const { s } = setup();
  for (const q of [0, -1, 1.5, '2', undefined]) assert.throws(() => s.reserve('A', q, 1000), /INVALID_QTY/);
});
test('reserve rejects more than available', () => {
  const { s } = setup();
  s.reserve('A', 8, 1000);
  assert.throws(() => s.reserve('A', 3, 1000), /INSUFFICIENT_STOCK/);
  s.reserve('A', 2, 1000);
  assert.strictEqual(s.getAvailable('A'), 0);
  assert.throws(() => s.reserve('B', 1, 1000), /INSUFFICIENT_STOCK/);
});
test('reservation expires exactly at creation + ttl', () => {
  const { s, advance } = setup();
  s.reserve('A', 4, 100);
  advance(99);
  assert.strictEqual(s.getAvailable('A'), 6);
  advance(1);
  assert.strictEqual(s.getAvailable('A'), 10);
  s.reserve('A', 10, 100); // expired stock is available again
});
test('confirm sells reserved stock and removes the reservation', () => {
  const { s } = setup();
  const id = s.reserve('A', 4, 1000);
  s.confirm(id);
  assert.strictEqual(s.getStock('A'), 6);
  assert.strictEqual(s.getAvailable('A'), 6);
  assert.throws(() => s.confirm(id), /RESERVATION_NOT_FOUND/);
});
test('confirm errors for unknown, released and expired ids', () => {
  const { s, advance } = setup();
  assert.throws(() => s.confirm('nope'), /RESERVATION_NOT_FOUND/);
  const released = s.reserve('A', 1, 1000);
  s.release(released);
  assert.throws(() => s.confirm(released), /RESERVATION_NOT_FOUND/);
  const expired = s.reserve('A', 1, 50);
  advance(50);
  assert.throws(() => s.confirm(expired), /RESERVATION_EXPIRED/);
  assert.strictEqual(s.getStock('A'), 10);
});
test('release frees stock and is idempotent', () => {
  const { s } = setup();
  const id = s.reserve('A', 5, 1000);
  s.release(id);
  s.release(id);
  s.release('unknown');
  assert.strictEqual(s.getAvailable('A'), 10);
});
test('removeItem cannot remove reserved stock', () => {
  const { s, advance } = setup();
  s.reserve('A', 7, 100);
  assert.throws(() => s.removeItem('A', 4), /INSUFFICIENT_STOCK/);
  s.removeItem('A', 3);
  assert.strictEqual(s.getStock('A'), 7);
  assert.strictEqual(s.getAvailable('A'), 0);
  advance(100);
  s.removeItem('A', 7);
  assert.strictEqual(s.getStock('A'), 0);
});

test('API: GET /stock includes available', () => {
  const { s } = setup();
  s.reserve('A', 3, 1000);
  assert.deepStrictEqual(createApi(s)({ method: 'GET', path: '/stock/A' }), { status: 200, body: { sku: 'A', stock: 10, available: 7 } });
});
test('API: reservation lifecycle and errors', () => {
  const { s, advance } = setup();
  const api = createApi(s);
  const created = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 4, ttlMs: 100 } });
  assert.strictEqual(created.status, 201);
  assert.strictEqual(typeof created.body.id, 'string');
  assert.deepStrictEqual(api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 7, ttlMs: 100 } }), { status: 409, body: { error: 'INSUFFICIENT_STOCK' } });
  assert.deepStrictEqual(api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 0, ttlMs: 100 } }), { status: 400, body: { error: 'INVALID_QTY' } });
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${created.body.id}/confirm` }), { status: 200, body: { sku: 'A', stock: 6 } });
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${created.body.id}/confirm` }), { status: 404, body: { error: 'RESERVATION_NOT_FOUND' } });

  const exp = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 1, ttlMs: 10 } }).body.id;
  advance(10);
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${exp}/confirm` }), { status: 410, body: { error: 'RESERVATION_EXPIRED' } });

  const rel = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 2, ttlMs: 100 } }).body.id;
  assert.strictEqual(api({ method: 'DELETE', path: `/reservations/${rel}` }).status, 204);
  assert.strictEqual(api({ method: 'DELETE', path: `/reservations/${rel}` }).status, 204);
  assert.strictEqual(api({ method: 'GET', path: '/stock/A' }).body.available, 6);
});
